-- Migration 0013 : documents liés à la session (étapes "avant / pendant /
-- après formation" du workflow) — devis, convention, contrat, convocation,
-- feuille d'émargement, attestation de fin de formation.
-- Rédaction originale (pas de contenu source Pivot Formation pour ceux-ci,
-- contrairement aux 15 documents transverses de la migration 0009) — cf.
-- claude/journal-avancement.md "Reste à faire" point 3.
-- Convention (art. L6353-1 et L6353-2 du Code du travail) et Contrat
-- (art. L6353-3 à L6353-7 du Code du travail, rétractation de 10 jours,
-- acompte plafonné à 30 %) à faire valider par Nora avant usage réel.

-- =========================================================
-- 1. Clauses juridiques (banque de contenu, réutilisables et modifiables
--    depuis le futur back-office sans toucher au code) — types dédiés pour
--    ne pas se mélanger avec le type 'legal_clause' déjà utilisé par les
--    trames de sous-traitance / partenariat (migration 0009).
-- =========================================================

insert into content_blocks (category_id, type, code, text, is_active) values
(null, 'legal_clause_convention', 'CONV_CL_01_OBJET', 'La présente convention est conclue en application des articles L6353-1 et L6353-2 du Code du travail. Elle a pour objet la réalisation d''une action de formation professionnelle entrant dans le champ d''application de l''article L6313-1 du Code du travail, organisée par {{company_name}} au bénéfice du personnel de l''entreprise ou de l''organisme cocontractant.', true),
(null, 'legal_clause_convention', 'CONV_CL_02_INTITULE_DUREE', 'Intitulé de la formation : {{training_name}}. Durée : {{training_duration}} heures. Dates prévisionnelles : du {{training_start_date}} au {{training_end_date}}. Modalité : {{training_modality}}. Lieu : {{training_location}}. Nombre de participants prévu : {{participant_count}}.', true),
(null, 'legal_clause_convention', 'CONV_CL_03_OBJECTIFS_PROGRAMME', 'Les objectifs pédagogiques et le programme détaillé de la formation figurent dans le document « Programme de formation » remis préalablement au cocontractant et annexé à la présente convention.', true),
(null, 'legal_clause_convention', 'CONV_CL_04_MOYENS', '{{company_name}} met en œuvre les moyens pédagogiques, techniques et d''encadrement décrits dans le programme de formation annexé, adaptés au format {{training_modality}} et au public visé.', true),
(null, 'legal_clause_convention', 'CONV_CL_05_EVALUATION_SANCTION', 'Les modalités d''évaluation des acquis sont précisées dans le programme de formation. À l''issue de l''action, {{company_name}} délivre une attestation de fin de formation mentionnant les résultats de l''évaluation des acquis, ainsi qu''une feuille d''émargement signée par demi-journée.', true),
(null, 'legal_clause_convention', 'CONV_CL_06_PRIX_REGLEMENT', 'Le prix de l''action de formation est fixé à {{price_amount_formatted}} ({{price_unit_label}}). Modalités de règlement : {{payment_terms}}. Toute somme versée fait l''objet d''une facture émise par {{company_name}}.', true),
(null, 'legal_clause_convention', 'CONV_CL_07_DEDIT_ANNULATION', 'En cas de résiliation à l''initiative de l''une des parties moins de dix jours ouvrés avant le début de l''action, et sauf cas de force majeure dûment reconnu, une indemnité correspondant aux frais déjà engagés par {{company_name}} pourra être due, dans la limite des dispositions applicables. En cas d''abandon en cours de formation par un participant, seules les prestations effectivement dispensées sont dues, sauf disposition contraire prévue par le financeur.', true),
(null, 'legal_clause_convention', 'CONV_CL_08_DIFFERENDS', 'Si un différend survient à l''occasion de l''interprétation ou de l''exécution de la présente convention, les parties s''efforcent de le résoudre à l''amiable. À défaut d''accord, le litige est porté devant le {{jurisdiction}}.', true),
(null, 'legal_clause_convention', 'CONV_CL_09_DONNEES_PERSONNELLES', 'Les données à caractère personnel des participants sont traitées par {{company_name}} conformément au Règlement Général sur la Protection des Données (RGPD), dans le seul cadre de l''exécution de la présente convention et de ses obligations Qualiopi. Contact : {{dpo_contact_email}}.', true),

(null, 'legal_clause_contrat', 'CONTRAT_CL_01_OBJET', 'Le présent contrat est conclu en application des articles L6353-3 à L6353-7 du Code du travail. Il a pour objet la réalisation, par {{company_name}}, d''une action de formation professionnelle au bénéfice de {{student_name}}, qui s''inscrit à titre individuel et à ses frais personnels.', true),
(null, 'legal_clause_contrat', 'CONTRAT_CL_02_INTITULE_PROGRAMME', 'Intitulé de la formation : {{training_name}}. Durée : {{training_duration}} heures. Dates prévisionnelles : du {{training_start_date}} au {{training_end_date}}. Modalité : {{training_modality}}. Lieu : {{training_location}}. Le programme détaillé, les objectifs pédagogiques et les prérequis sont annexés au présent contrat.', true),
(null, 'legal_clause_contrat', 'CONTRAT_CL_03_MOYENS_EVALUATION', '{{company_name}} met en œuvre les moyens pédagogiques, techniques et d''encadrement décrits dans le programme annexé. Les modalités d''évaluation des acquis et la nature de la sanction délivrée à l''issue de la formation (attestation de fin de formation) sont également précisées dans ce programme.', true),
(null, 'legal_clause_contrat', 'CONTRAT_CL_04_PRIX', 'Le prix de la formation est fixé à {{price_amount_formatted}} ({{price_unit_label}}). {{payment_terms}}', true),
(null, 'legal_clause_contrat', 'CONTRAT_CL_05_RETRACTATION', 'Conformément à l''article L6353-5 du Code du travail, {{student_name}} dispose d''un délai de dix jours, à compter de la signature du présent contrat, pour se rétracter. Il en informe {{company_name}} par lettre recommandée avec accusé de réception. Aucune somme ne peut être exigée avant l''expiration de ce délai.', true),
(null, 'legal_clause_contrat', 'CONTRAT_CL_06_ACOMPTE', 'À l''expiration du délai de rétractation, {{student_name}} s''acquitte, conformément à l''article L6353-6 du Code du travail, d''un acompte qui ne peut excéder 30 % du prix total de la formation ; le solde est réglé selon les modalités précisées à l''article « Prix ».', true),
(null, 'legal_clause_contrat', 'CONTRAT_CL_07_INEXECUTION', 'Si {{student_name}} abandonne la formation en cours d''exécution du contrat pour un motif autre que la force majeure dûment reconnue, le contrat est résilié. Conformément à l''article L6353-7 du Code du travail, seules sont dues à {{company_name}} les sommes correspondant aux prestations effectivement dispensées, évaluées au prorata temporis de leur valeur prévue au contrat, en sus, le cas échéant, d''une indemnité qui ne peut excéder 30 % du montant correspondant à la partie non exécutée du contrat.', true),
(null, 'legal_clause_contrat', 'CONTRAT_CL_08_DIFFERENDS', 'En cas de différend né de l''interprétation ou de l''exécution du présent contrat, les parties s''efforcent de trouver une solution amiable. À défaut, le litige relève du {{jurisdiction}}.', true),
(null, 'legal_clause_contrat', 'CONTRAT_CL_09_DONNEES_PERSONNELLES', 'Les données à caractère personnel de {{student_name}} sont traitées par {{company_name}} conformément au RGPD, dans le seul cadre de l''exécution du présent contrat. Contact : {{dpo_contact_email}}.', true);

