insert into document_template_sections (document_template_id, code, title, sort_order, content_type, html_template, source_content_block_type, content_block_scope) values

-- ---------- DEVIS ----------
('devis', 'header', 'En-tête', 1, 'rich_text', '<p>{{company_name}} — {{address}}<br/>SIRET {{siret}} — {{phone}} — {{email}}</p><p><strong>DEVIS N° {{quote_reference}}</strong><br/>Date d''émission : {{generated_date}}<br/>Validité : 30 jours à compter de la date d''émission</p><p><strong>Destinataire :</strong><br/>{{student_name}}<br/>{{student_company}}</p>', null, 'global'),
('devis', 'prestation', 'Prestation proposée', 2, 'rich_text', '<table><tbody><tr><th>Formation</th><td>{{training_name}}</td></tr><tr><th>Durée</th><td>{{training_duration}} heures</td></tr><tr><th>Dates prévisionnelles</th><td>Du {{training_start_date}} au {{training_end_date}}</td></tr><tr><th>Modalité</th><td>{{training_modality}}</td></tr><tr><th>Lieu</th><td>{{training_location}}</td></tr><tr><th>Nombre de participants</th><td>{{participant_count}}</td></tr></tbody></table>', null, 'global'),
('devis', 'tarif', 'Tarif', 3, 'rich_text', '<table><tbody><tr><th>{{price_unit_label}}</th><td>{{price_amount_formatted}}</td></tr></tbody></table><p>Mode de financement envisagé : {{funding_type_label}} {{funding_details}}</p>', null, 'global'),
('devis', 'modalites_reglement', 'Modalités de règlement', 4, 'rich_text', '<p>{{payment_terms}}</p>', null, 'global'),
('devis', 'conditions', 'Conditions', 5, 'rich_text', '<p>Ce devis constitue une proposition commerciale et ne vaut pas engagement contractuel définitif. Il sera formalisé, selon le mode de financement retenu, par une convention de formation professionnelle ou un contrat de formation professionnelle, conformément aux articles L6353-1 et suivants du Code du travail. Les conditions générales de vente de {{company_name}} sont disponibles sur demande.</p>', null, 'global'),
('devis', 'acceptation', 'Bon pour accord', 6, 'rich_text', '<table style="width:100%; margin-top:8pt;"><tbody><tr><td style="width:50%; vertical-align:top;">Pour {{company_name}}<br/>{{director_name}}<br/><br/>Date et signature :<br/><br/><br/></td><td style="width:50%; vertical-align:top;">Pour le client<br/>{{student_name}} — {{student_company}}<br/><br/>Date et signature (précédée de la mention manuscrite « Bon pour accord ») :<br/><br/><br/></td></tr></tbody></table>', null, 'global'),

-- ---------- CONVENTION DE FORMATION (tiers financeur) ----------
('convention_formation', 'header', 'Parties', 1, 'rich_text', '<p><strong>Entre les soussignés :</strong></p><p><strong>L''organisme de formation :</strong> {{company_name}} ({{commercial_name}}), SIRET {{siret}}, {{address}}, représenté par {{director_name}}, ci-après « l''organisme »,</p><p><strong>Et le cocontractant :</strong> {{student_company}}, représenté par ……………………………, ci-après « le cocontractant »,</p><p>Il est convenu ce qui suit — Référence : {{convention_reference}} — Fait à {{organization_city}}, le {{generated_date}}.</p>', null, 'global'),
('convention_formation', 'clauses', 'Articles', 2, 'content_block_list', null, 'legal_clause_convention', 'global'),
('convention_formation', 'annexes', 'Annexes', 3, 'rich_text', '<p>Sont annexés à la présente convention et en font partie intégrante : le programme de formation détaillé, le devis {{quote_reference}}, le règlement intérieur de {{company_name}}.</p>', null, 'global'),
('convention_formation', 'signatures', 'Signatures', 4, 'rich_text', '<table style="width:100%; margin-top:8pt;"><tbody><tr><td style="width:50%; vertical-align:top;">Pour l''organisme, {{company_name}}<br/>{{director_name}}<br/><br/>Date et signature :<br/><br/><br/></td><td style="width:50%; vertical-align:top;">Pour le cocontractant, {{student_company}}<br/><br/>Date et signature (précédée de la mention manuscrite « Lu et approuvé, bon pour accord ») :<br/><br/><br/></td></tr></tbody></table>', null, 'global'),

-- ---------- CONTRAT DE FORMATION (particulier autofinancé) ----------
('contrat_formation_particulier', 'header', 'Parties', 1, 'rich_text', '<p><strong>Entre les soussignés :</strong></p><p><strong>L''organisme de formation :</strong> {{company_name}} ({{commercial_name}}), SIRET {{siret}}, {{address}}, représenté par {{director_name}}, ci-après « l''organisme »,</p><p><strong>Et le stagiaire :</strong> {{student_name}}, ci-après « le stagiaire »,</p><p>Il est convenu ce qui suit — Fait à {{organization_city}}, le {{generated_date}}.</p>', null, 'global'),
('contrat_formation_particulier', 'clauses', 'Articles', 2, 'content_block_list', null, 'legal_clause_contrat', 'global'),
('contrat_formation_particulier', 'annexes', 'Annexes', 3, 'rich_text', '<p>Sont annexés au présent contrat et en font partie intégrante : le programme de formation détaillé et le règlement intérieur de {{company_name}}.</p>', null, 'global'),
('contrat_formation_particulier', 'signatures', 'Signatures', 4, 'rich_text', '<table style="width:100%; margin-top:8pt;"><tbody><tr><td style="width:50%; vertical-align:top;">Pour l''organisme, {{company_name}}<br/>{{director_name}}<br/><br/>Date et signature :<br/><br/><br/></td><td style="width:50%; vertical-align:top;">Le stagiaire, {{student_name}}<br/><br/>Date et signature (précédée de la mention manuscrite « Lu et approuvé, bon pour accord ») :<br/><br/><br/></td></tr></tbody></table>', null, 'global'),

-- ---------- CONVOCATION ----------
('convocation', 'header', 'En-tête', 1, 'rich_text', '<p>{{company_name}} — {{address}}<br/>{{phone}} — {{email}}</p><p>{{organization_city}}, le {{generated_date}}</p><p><strong>Destinataire :</strong><br/>{{student_name}}<br/>{{student_company}}</p>', null, 'global'),
('convocation', 'objet', 'Objet', 2, 'rich_text', '<p>Nous avons le plaisir de vous convoquer à la formation <strong>« {{training_name}} »</strong>, dispensée par {{company_name}}.</p><table><tbody><tr><th>Dates</th><td>Du {{training_start_date}} au {{training_end_date}}</td></tr><tr><th>Durée</th><td>{{training_duration}} heures</td></tr><tr><th>Modalité</th><td>{{training_modality}}</td></tr><tr><th>Lieu</th><td>{{training_location}}</td></tr><tr><th>Formateur·rice</th><td>{{trainer_name}}</td></tr></tbody></table>', null, 'global'),
('convocation', 'infos_pratiques', 'Informations pratiques', 3, 'checklist', 'Se munir d''une pièce d''identité en cours de validité
Prévoir de quoi prendre des notes (le support de formation est fourni par ailleurs)
Pour une formation à distance : disposer d''une connexion internet stable et d''un accès à {{technical_provider_name}}
Prévenir {{administrative_referent_name}} au plus tôt en cas d''empêchement', null, 'global'),
('convocation', 'contact', 'Contacts', 4, 'rich_text', '<p>Pour toute question sur le contenu de la formation, vous pouvez contacter {{pedagogical_referent_name}} ({{pedagogical_referent_email}} / {{pedagogical_referent_phone}}).</p><p>Si vous êtes en situation de handicap et souhaitez signaler un besoin d''aménagement, contactez {{disability_referent_name}} ({{disability_referent_email}}).</p>', null, 'global'),
('convocation', 'signature', 'Signature', 5, 'signature_block', null, null, 'global'),

-- ---------- FEUILLE D'ÉMARGEMENT ----------
('feuille_emargement', 'header', 'En-tête', 1, 'rich_text', '<p>{{company_name}} — {{address}}</p><p><strong>FEUILLE D''ÉMARGEMENT</strong></p><table><tbody><tr><th>Formation</th><td>{{training_name}}</td></tr><tr><th>Dates</th><td>Du {{training_start_date}} au {{training_end_date}}</td></tr><tr><th>Lieu</th><td>{{training_location}}</td></tr><tr><th>Formateur·rice</th><td>{{trainer_name}}</td></tr></tbody></table><p class="empty">Une feuille est à compléter pour chaque demi-journée de formation (matin / après-midi) — dupliquer cette page autant que nécessaire, en indiquant la date et le créneau ci-dessous.</p><p>Date : …………………………… &nbsp; Créneau : ☐ Matin &nbsp; ☐ Après-midi</p>', null, 'global'),
('feuille_emargement', 'table_emargement', 'Émargement', 2, 'rich_text', '<table><thead><tr><th>N°</th><th>Nom et prénom</th><th>Signature</th></tr></thead><tbody><tr><td>1</td><td>{{student_name}}</td><td></td></tr><tr><td>2</td><td></td><td></td></tr><tr><td>3</td><td></td><td></td></tr><tr><td>4</td><td></td><td></td></tr><tr><td>5</td><td></td><td></td></tr><tr><td>6</td><td></td><td></td></tr><tr><td>7</td><td></td><td></td></tr><tr><td>8</td><td></td><td></td></tr></tbody></table><p style="margin-top:12pt;">Signature du formateur / de la formatrice : ……………………………</p>', null, 'global'),
('feuille_emargement', 'mentions', 'Mentions', 3, 'rich_text', '<p>La présente feuille d''émargement est signée par chaque participant à chaque demi-journée de formation. Elle constitue, avec les évaluations et l''attestation de fin de formation, un justificatif de la réalisation effective de l''action, conservé par {{company_name}} pendant {{archiving_duration}}.</p>', null, 'global'),

-- ---------- ATTESTATION DE FIN DE FORMATION ----------
('attestation_fin_formation', 'header', 'En-tête', 1, 'rich_text', '<p>{{company_name}} — {{address}}<br/>SIRET {{siret}}</p><p style="text-align:center; font-weight:600; font-size:13pt; margin-top:16pt;">ATTESTATION DE FIN DE FORMATION</p><p style="text-align:center;">Délivrée en application de l''article L6353-1 du Code du travail.</p>', null, 'global'),
('attestation_fin_formation', 'identification', 'Identification', 2, 'rich_text', '<p>Je soussigné(e) {{director_name}}, représentant {{company_name}}, atteste que :</p><p><strong>{{student_name}}</strong><br/>{{student_company}}</p><p>a suivi l''action de formation intitulée <strong>« {{training_name}} »</strong>, du {{training_start_date}} au {{training_end_date}}, d''une durée de {{training_duration}} heures, dispensée en modalité {{training_modality}} à {{training_location}}.</p>', null, 'global'),
('attestation_fin_formation', 'resultats', 'Nature de l''action et résultats', 3, 'rich_text', '<p><strong>Nature de l''action :</strong> action de formation entrant dans le champ d''application de l''article L6313-1 du Code du travail.</p><p><strong>Objectifs :</strong> conformes au programme de formation remis en amont de l''action.</p><p><strong>Résultats de l''évaluation des acquis :</strong></p><ul><li>☐ Objectifs de la formation atteints</li><li>☐ Objectifs partiellement atteints</li><li>☐ Objectifs non atteints</li></ul><p>Assiduité constatée sur la base de la feuille d''émargement : …..…… heures sur {{training_duration}} heures.</p>', null, 'global'),
('attestation_fin_formation', 'mention_legale', 'Mention légale', 4, 'rich_text', '<p>Cette attestation est délivrée pour permettre au bénéficiaire de faire valoir son droit à la formation, notamment auprès de son employeur ou d''un organisme financeur. Elle est distincte du certificat de réalisation le cas échéant transmis au financeur.</p>', null, 'global'),
('attestation_fin_formation', 'signature', 'Signature', 5, 'signature_block', null, null, 'global');
